function text(v) { return v == null ? '' : String(v).trim(); }
function digits(v) { return text(v).replace(/[\s-]/g, '').toUpperCase(); }
function valid10(v) {
  if (!/^[0-9]{9}[0-9X]$/.test(v)) return false;
  let sum = 0;
  for (let i = 0; i < 10; i++) sum += (v[i] === 'X' ? 10 : Number(v[i])) * (10 - i);
  return sum % 11 === 0;
}
function valid13(v) {
  if (!/^\d{13}$/.test(v)) return false;
  let sum = 0;
  for (let i = 0; i < 13; i++) sum += Number(v[i]) * (i % 2 === 0 ? 1 : 3);
  return sum % 10 === 0;
}
function to13(v) {
  const body = '978' + v.slice(0, 9);
  let sum = 0;
  for (let i = 0; i < 12; i++) sum += Number(body[i]) * (i % 2 === 0 ? 1 : 3);
  return body + String((10 - sum % 10) % 10);
}
function norm(v) {
  return text(v).normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
    .replace(/&/g, ' and ').replace(/['\u2018\u2019]/g, '').replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ').trim()
    .replace(/^(the|a|an)\s+/, '');
}
function year(v) { const m = text(v).match(/\b(1[0-9]{3}|20[0-9]{2}|2100)\b/); return m ? Number(m[1]) : null; }
const row = $input.item.json;
const raw = digits(row.ISBN);
const isbn10 = valid10(raw) ? raw : null;
const isbn13 = valid13(raw) ? raw : (isbn10 ? to13(isbn10) : null);
const ok = Boolean(isbn10 || isbn13);
return { json: {
  ...row, isbn10, isbn13, isbn_clean: isbn13 || isbn10, isbn_valid: ok,
  title_source: text(row['Book Title']) || null, author_source: text(row.Author) || null,
  publisher_source: text(row.Publisher) || null, year_source: year(row.Year),
  category_source: text(row.Category) || null,
  title_normalized: norm(row['Book Title']), author_normalized: norm(row.Author),
  status: ok ? 'received' : 'manual_review',
  review_reason: ok ? null : (!raw ? 'missing_or_invalid_isbn' : 'invalid_isbn_checksum'),
  retry_count: 0
} };

const j = $input.item.json;
const status = j.error?.statusCode || j.statusCode || null;
const retryable = [429, 500, 502, 503, 504].includes(Number(status));
return { json: { ...j, status: retryable ? 'metadata_retryable_error' : 'manual_review', review_reason: retryable ? 'metadata_fetch_failed_after_retries' : 'metadata_not_found', error_code: String(status || 'metadata_empty_or_error') } };

const original = $('Validate ISBN').item.json;
const response = $input.item.json;
const book = response?.items?.[0]?.volumeInfo || {};
const clean = v => v == null || String(v).trim() === '' ? null : String(v).trim();
const parsedYear = v => { const m = String(v || '').match(/\\b(1[0-9]{3}|20[0-9]{2}|2100)\\b/); return m ? Number(m[1]) : null; };
const authors = Array.isArray(book.authors) ? book.authors.map(clean).filter(Boolean) : [];
const categories = Array.isArray(book.categories) ? book.categories.map(clean).filter(Boolean) : [];
const title = clean(book.title) || original.title_source || clean(original['Book Title']);
const author = authors.join('; ') || original.author_source || clean(original.Author);
const publisher = clean(book.publisher) || original.publisher_source || clean(original.Publisher);
const year = parsedYear(book.publishedDate) || original.year_source;
const category = categories[0] || original.category_source || clean(original.Category) || 'Uncategorized';
return { json: { ...original, isbn: original.isbn13 || original.isbn10 || original.isbn_clean, title_raw: title, author_raw: author, publisher_raw: publisher, year_raw: year, category_raw: category, title_normalized: original.title_normalized, author_normalized: original.author_normalized, metadata_source: book.title ? 'google_books' : 'source_file', metadata_confidence: book.title ? 0.85 : 0.50, metadata_found: Boolean(book.title), metadata: { volume_id: clean(response?.items?.[0]?.id), authors, categories }, status: book.title ? 'metadata_success' : 'manual_review', review_reason: book.title ? null : 'metadata_not_found' } };

const data = $getWorkflowStaticData('global');
data.seenBooks = data.seenBooks || {};
const item = $input.item.json;
function norm(v) { return String(v || '').normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim().replace(/^(the|a|an)\s+/, ''); }
const key = item.isbn13 || item.isbn10 || item.isbn_clean || `${item.title_normalized || norm(item['Book Title'])}|${item.author_normalized || norm(item.Author)}`;
const duplicate = Boolean(data.seenBooks[key]);
data.seenBooks[key] = true;
return { json: { ...item, is_duplicate: duplicate, duplicate_key: key } };

function titleCase(s) {
  if (!s) return s;
  return s.split(' ').map(word => {
    if (!word) return word;
    if (/^[A-Z]{2,}$/.test(word)) return word;
    if (/\./.test(word)) return word;
    if (/^(Mc|Mac)[A-Z]/.test(word)) return word;
    return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
  }).join(' ');
}

const CATEGORY_MAP = {
  physics: 'Science > Physics', chemistry: 'Science > Chemistry', biology: 'Science > Biology',
  math: 'Mathematics', history: 'Social Studies > History', fiction: 'Literature > Fiction'
};

const item = $input.item.json;
const rawCategory = (item.category_raw || '').toLowerCase();
const mappedCategory = CATEGORY_MAP[rawCategory] || item.category_raw || 'Uncategorized';

return {
  json: {
    isbn: item.isbn || item.isbn_clean,
    title: titleCase(item.title_raw),
    author: titleCase(item.author_raw),
    publisher: item.publisher_raw,
    year: item.year_raw,
    category: mappedCategory,
    processed: true,
    processed_at: new Date().toISOString()
  }
};

const data = $getWorkflowStaticData('global');
const rows = Array.isArray(data.runResults) ? data.runResults : [];
let updated = 0, missingIsbn = 0, duplicates = 0, errors = 0, manualReview = 0, unclassified = 0;
for (const j of rows) {
  const reason = String(j.review_reason || '').toLowerCase();
  const status = String(j.status || '').toLowerCase();
  if (j.processed === true || ['catalog_upserted','processed','catalog_ready'].includes(status)) updated++;
  else if (j.is_duplicate === true || reason === 'duplicate_entry' || status === 'duplicate') { duplicates++; manualReview++; }
  else if (['missing_or_invalid_isbn','missing_isbn','invalid_isbn_checksum'].includes(reason) || status === 'invalid_input') { missingIsbn++; manualReview++; }
  else if (['metadata_fetch_failed_after_retries','metadata_retryable_error','metadata_permanent_error','write_failed'].includes(reason) || ['metadata_retryable_error','metadata_permanent_error','write_failed'].includes(status)) { errors++; manualReview++; }
  else if (reason || ['manual_review','metadata_not_found'].includes(status)) manualReview++;
  else { unclassified++; manualReview++; }
}
return { json: { run_id: data.runId || $execution.id, total_books: rows.length, updated, missing_isbn: missingIsbn, duplicates, errors, manual_review: manualReview, unclassified, librarian_email: 'user@example.com', summary_generated_at: new Date().toISOString() } };

