const data = $getWorkflowStaticData('global');
data.seenBooks = {};
data.runResults = [];
data.runId = $execution.id;
function norm(v) { return String(v || '').normalize('NFKD').replace(/[\\u0300-\\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').replace(/\\s+/g, ' ').trim(); }
for (const row of $input.all()) {
  const j = row.json;
  const isbn = String(j.ISBN || j.isbn || '').replace(/[\\s-]/g, '').toUpperCase();
  const key = isbn || `${norm(j.Title || j.title)}|${norm(j.Author || j.author)}`;
  if (key !== '|') data.seenBooks[key] = true;
}
return $('Parse Uploaded Spreadsheet').all();

if (!$binary?.data) throw new Error('Missing upload binary property data');
if ($binary.data.fileSize && Number($binary.data.fileSize) > 10485760) throw new Error('Upload exceeds 10 MB');
const fileName = ($binary.data.fileName || '').toLowerCase();
if (!fileName.endsWith('.xlsx')) throw new Error('Unsupported file type - upload an .xlsx workbook');
return {json: $json, binary: $binary};

const data = $getWorkflowStaticData('global');
data.runResults = data.runResults || [];
const j = { ...$input.item.json };
data.runResults.push({
  run_id: data.runId || $execution.id,
  source_row_number: j.source_row_number || null,
  status: j.status || (j.processed === true ? 'catalog_upserted' : 'manual_review'),
  processed: j.processed === true,
  is_duplicate: j.is_duplicate === true,
  review_reason: j.review_reason || null,
  error_code: j.error_code || null
});
return { json: j };

